CREATE OR REPLACE VIEW `vwprovv2cogestorno` AS select `p`.`id` AS `id`,`p`.`entrata_uscita` AS `entrata_uscita`,`p`.`fonte` AS `fonte`,`p`.`data_status` AS `data_status`,-(abs(`p`.`importo`)) AS `importo`,(curdate() - interval (dayofmonth(curdate()) - 1) day) AS `datacontabile` from `provvigioni` `p` where ((`p`.`data_status` >= ((curdate() - interval (dayofmonth(curdate()) - 1) day) - interval 2 month)) and (`p`.`data_status` <= ((curdate() - interval 1 month) - interval dayofmonth((curdate() - interval 1 month)) day)) and (`p`.`status_pratica` in ('PERFEZIONATA','IN AMMORTAMENTO'))) order by `p`.`entrata_uscita`,`p`.`data_status`
